import {LIMITS,decodeLocal,makeCheckedPNG,normalizeRect,checkRects} from './core.js';
const $=id=>document.getElementById(id), canvas=$('canvas'), ctx=canvas.getContext('2d');
let source=null,info=null,regions=[],selected=null,undo=[],redo=[],nextId=1,version=0,checked=null,view='edit',drag=null,busy=false,loadId=0,fieldsDirty=false;
const copy=()=>regions.map(r=>({...r}));
function say(text){$('announcement').textContent=text;}
function error(text){$('error').textContent=text;$('error').hidden=!text;if(text)say(text);}
function invalidate(){version++;checked=null;view='edit';fieldsDirty=false;$('reviewed').checked=false;$('download-status').textContent='';}
function commit(next,choice=selected){undo.push(copy());if(undo.length>50)undo.shift();redo=[];regions=next;selected=choice;invalidate();error('');render();}
function selectedRegion(){return regions.find(r=>r.id===selected);}
function draw(){if(!source)return;canvas.width=source.width;canvas.height=source.height;ctx.drawImage(view==='checked'&&checked?checked.canvas:source,0,0);if(view==='edit'){ctx.fillStyle='#171d20';for(const r of regions)ctx.fillRect(r.x,r.y,r.width,r.height);const r=drag?drag.preview:selectedRegion();if(r){const scale=canvas.width/(canvas.getBoundingClientRect().width||canvas.width);ctx.strokeStyle='#4081b6';ctx.lineWidth=Math.max(1,2*scale);ctx.setLineDash([5*scale,3*scale]);ctx.strokeRect(r.x,r.y,r.width,r.height);}}}
function render(){
  fieldsDirty=false;
  $('cancel-coordinates').hidden=true;
  $('empty').hidden=!!source;$('editor').hidden=!source;if(!source)return;
  $('dimensions').textContent=`${info.width.toLocaleString()} × ${info.height.toLocaleString()} px · ${info.format}`;
  $('region-count').textContent=regions.length;$('no-regions').hidden=regions.length>0;$('regions').replaceChildren();
  regions.forEach((r,i)=>{const li=document.createElement('li'),b=document.createElement('button'),s=document.createElement('span'),small=document.createElement('small');s.textContent=`Region ${i+1}`;small.textContent=`${r.width} × ${r.height}`;b.append(s,small);b.setAttribute('aria-pressed',r.id===selected);b.addEventListener('click',()=>{selected=r.id;view='edit';render();});li.append(b);$('regions').append(li);});
  const r=selectedRegion();$('coordinates').hidden=!r;if(r){$('selected-label').textContent=`Region ${regions.indexOf(r)+1}`;for(const k of ['x','y','width','height'])$(k).value=r[k];$('x').max=source.width-1;$('y').max=source.height-1;$('width').max=source.width;$('height').max=source.height;}
  $('edit-view').setAttribute('aria-pressed',view==='edit');$('checked-view').setAttribute('aria-pressed',view==='checked');$('checked-view').disabled=!checked||busy;
  $('undo').disabled=!undo.length||busy;$('redo').disabled=!redo.length||busy;$('add').disabled=regions.length>=LIMITS.zones||busy;$('verify').disabled=!regions.length||busy;
  for(const id of ['change','clear','remove','edit-view'])$(id).disabled=busy;
  for(const el of $('coordinates').elements)el.disabled=busy;
  $('check-results').hidden=!checked;$('verify').hidden=!!checked;$('check-state').textContent=busy?'Checking exact PNG…':checked?'File checks passed':'Not checked';$('status-dot').classList.toggle('passed',!!checked);
  $('check-copy').textContent=busy?'Encoding a new image, reopening its bytes, and checking the selected pixels.':checked?'Review the checked image before you save it. These checks do not detect missed details.':regions.length?'Your edits are not checked yet. Build a new PNG to inspect its actual bytes.':'Add regions, then build and check a new PNG.';
  $('view-caption').textContent=view==='checked'?'Exact checked PNG bytes.':'Drag to cover a region.';$('canvas-help').textContent=view==='checked'?'Switch to Edit regions to make changes.':'Drag to cover. Select a region to adjust it.';$('final-note').hidden=view!=='checked';
  if(checked){$('hash').textContent=checked.report.sha256;$('export-size').textContent=`PNG · ${(checked.report.bytes/1024).toFixed(1)} KiB · ${checked.report.regions} region${checked.report.regions===1?'':'s'}`;}
  $('download').disabled=!checked||!$('reviewed').checked||busy;draw();
}
function releaseSource(){if(source){source.width=1;source.height=1;}source=null;info=null;regions=[];undo=[];redo=[];selected=null;checked=null;drag=null;version++;}
async function load(file,synthetic=false){const id=++loadId;error('');say('Opening image locally.');try{const result=await decodeLocal(file);if(id!==loadId){result.canvas.width=1;return;}releaseSource();source=result.canvas;info=result.info;view='edit';$('image-label').textContent=synthetic?'Synthetic support example':'Local image';$('file').value='';$('reviewed').checked=false;render();say(`${synthetic?'Synthetic example':'Image'} loaded. ${info.width} by ${info.height} pixels. Add a region or drag on the image.`);}catch(e){if(id===loadId){$('file').value='';error(e.message||'The browser could not decode this image. Try a supported PNG or JPEG.');}}}
$('open').onclick=()=>$('file').click();$('change').onclick=()=>$('file').click();$('file').onchange=()=>{if($('file').files[0])load($('file').files[0]);};
$('sample').onclick=()=>{const c=document.createElement('canvas');c.width=1100;c.height=640;const x=c.getContext('2d');x.fillStyle='#fbfbf6';x.fillRect(0,0,c.width,c.height);x.fillStyle='#e6ece1';x.fillRect(0,0,1100,60);x.fillStyle='#45694d';x.font='16px system-ui';x.fillText('NORTHFIELD LAB     /     SUPPORT REQUEST',40,38);x.font='bold 12px system-ui';x.fillText('SYNTHETIC EXAMPLE — NO REAL PERSON OR CREDENTIAL',650,38);x.fillStyle='#28382c';x.font='bold 32px system-ui';x.fillText('My project will not sync',55,126);x.font='19px system-ui';x.fillStyle='#64705e';x.fillText('The same error appears after I retry. What should I check?',55,169);x.fillStyle='#e4eadd';x.fillRect(55,208,990,1);x.font='15px system-ui';x.fillStyle='#687b60';x.fillText('CONTACT',55,252);x.fillText('PROJECT TOKEN',55,331);x.fillStyle='#273b2d';x.font='22px monospace';x.fillText('mira.demo@example.invalid',55,285);x.fillText('DEMO-NOT-A-SECRET-7F42',55,364);x.fillStyle='#eef0e9';x.fillRect(55,413,990,148);x.fillStyle='#58634d';x.font='16px monospace';x.fillText('SYNC_ERROR 409',78,452);x.fillText('The remote revision changed. Pull the latest version and retry.',78,485);x.fillText('Build: demo-1.4 / Status: pending',78,524);x.fillStyle='#7f8979';x.font='13px system-ui';x.fillText('Example built in this browser. Mark the details you would not share.',55,607);c.toBlob(b=>load(b,true),'image/png');};
$('clear').onclick=()=>{loadId++;releaseSource();$('file').value='';error('');render();say('Session cleared. Your original files and existing downloads are unchanged.');$('open').focus();};
$('add').onclick=()=>{if(!source||busy||regions.length>=LIMITS.zones)return;const r={id:nextId++,x:Math.floor(source.width*.08),y:Math.floor(source.height*.12),width:Math.max(1,Math.floor(source.width*.34)),height:Math.max(1,Math.floor(source.height*.07))};commit([...copy(),r],r.id);$('x').focus();say('Region added. Adjust its coordinates.');};
$('coordinates').onsubmit=e=>{e.preventDefault();const r=selectedRegion();if(!r||busy)return;const next={id:r.id,...Object.fromEntries(['x','y','width','height'].map(k=>[k,Number($(k).value)]))};try{checkRects([next],source.width,source.height);commit(regions.map(p=>p.id===r.id?next:{...p}));say('Coordinates applied. Previous file checks invalidated.');}catch(ex){error(ex.message);}};
$('coordinates').oninput=()=>{if(busy)return;if(!fieldsDirty)invalidate();fieldsDirty=true;$('cancel-coordinates').hidden=false;$('check-results').hidden=true;$('verify').hidden=false;$('verify').disabled=true;$('checked-view').disabled=true;$('checked-view').setAttribute('aria-pressed','false');$('edit-view').setAttribute('aria-pressed','true');$('check-state').textContent='Apply coordinates first';$('status-dot').classList.remove('passed');$('check-copy').textContent='These coordinate changes are not applied yet. Apply or cancel them before building another PNG.';$('download').disabled=true;$('final-note').hidden=true;$('view-caption').textContent='Coordinate changes pending.';$('canvas-help').textContent='The image shows the last applied coordinates. Apply the new values to update it.';say('Coordinate changes pending. File checks cleared. Apply or cancel the coordinates before checking again.');draw();};
$('cancel-coordinates').onclick=()=>{render();error('');say('Coordinate changes canceled. Last applied coordinates restored. Build and check the PNG again.');};
$('remove').onclick=()=>{const id=selected;commit(regions.filter(r=>r.id!==id),regions.find(r=>r.id!==id)?.id??null);say('Region removed.');};
function history(back){const from=back?undo:redo,to=back?redo:undo;if(!from.length||busy)return;to.push(copy());regions=from.pop();selected=regions.at(-1)?.id??null;invalidate();render();say(back?'Undo applied. Check the new PNG again.':'Redo applied. Check the new PNG again.');}
$('undo').onclick=()=>history(true);$('redo').onclick=()=>history(false);
function point(event){const b=canvas.getBoundingClientRect();return{x:(event.clientX-b.left)*canvas.width/b.width,y:(event.clientY-b.top)*canvas.height/b.height};}
canvas.onpointerdown=e=>{if(!source||busy||view!=='edit'||e.button!==0)return;const p=point(e);const hit=[...regions].reverse().find(r=>p.x>=r.x&&p.x<r.x+r.width&&p.y>=r.y&&p.y<r.y+r.height);if(hit){selected=hit.id;render();return;}if(regions.length>=LIMITS.zones){error('Use no more than 50 regions.');return;}drag={start:p,preview:null};canvas.setPointerCapture(e.pointerId);};
canvas.onpointermove=e=>{if(!drag)return;try{const p=point(e);drag.preview=normalizeRect(drag.start.x,drag.start.y,p.x,p.y,source.width,source.height);}catch{drag.preview=null;}draw();};
canvas.onpointerup=e=>{if(!drag)return;const r=drag.preview;drag=null;if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);if(r){r.id=nextId++;commit([...copy(),r],r.id);say('Region added. Review its coverage.');}else draw();};
canvas.onpointercancel=()=>{drag=null;draw();};
canvas.onkeydown=e=>{if(busy||view!=='edit')return;const r=selectedRegion();if(!r)return;let delta=e.shiftKey?10:1;const movements={ArrowLeft:[-delta,0],ArrowRight:[delta,0],ArrowUp:[0,-delta],ArrowDown:[0,delta]};if(movements[e.key]){e.preventDefault();const [dx,dy]=movements[e.key];const n={...r,x:Math.max(0,Math.min(source.width-r.width,r.x+dx)),y:Math.max(0,Math.min(source.height-r.height,r.y+dy))};commit(regions.map(p=>p.id===r.id?n:{...p}));}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();$('remove').click();}};
$('verify').onclick=async()=>{if(busy||!source||fieldsDirty)return;const current=version,input=source,rects=copy();busy=true;error('');render();say('Building and checking the PNG.');try{await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));const result=await makeCheckedPNG(input,rects);if(current!==version||input!==source)return;checked=result;view='checked';$('reviewed').checked=false;say('PNG file checks passed. Review the checked image before downloading.');}catch(e){checked=null;error(e.message||'File checking failed. No download was prepared.');}finally{busy=false;render();}};
$('edit-view').onclick=()=>{view='edit';render();};$('checked-view').onclick=()=>{if(checked){view='checked';render();}};$('reviewed').onchange=()=>{$('download').disabled=!checked||!$('reviewed').checked;};
function save(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
$('download').onclick=()=>{if(!checked||!$('reviewed').checked)return;save(checked.blob,'covercheck.png');$('download-status').textContent='Download requested for the checked PNG. Check your browser downloads; this page cannot confirm where it was saved.';};
$('receipt').onclick=()=>{if(checked)save(new Blob([JSON.stringify(checked.report,null,2)+'\n'],{type:'application/json'}),'covercheck-report.json');};
for(const id of ['about-button','credits-button'])$(id).onclick=()=>$('about').showModal();$('close-about').onclick=()=>$('about').close();
window.addEventListener('resize',()=>{if(source)draw();});
